def провести_аудит(организация, системы, расчёты, подбор, проблемы_оборудования, справочник_сзи, документы_готовы=True):
 пункты=[]
 def добавить(название,статус,факт,причина,рекомендация): пункты.append({'проверка':название,'статус':статус,'исходный_факт':факт,'причина':причина,'рекомендация':рекомендация})
 добавить('Полнота паспорта и реестра','соответствует' if организация.get('название') and len(системы)>=3 else 'несоответствие',f"Организация заполнена; систем {len(системы)}",'Проверены обязательные поля и минимум три системы','Заполнить отсутствующие поля')
 допуст={'специальные','биометрические','общедоступные','иные'}; группы={'сотрудники','не_сотрудники'}
 bad=[s['номер'] for s in системы if s.get('категория_пдн') not in допуст or s.get('тип_субъектов') not in группы or s.get('тип_угроз_по_условию') not in (1,2,3) or not isinstance(s.get('количество_субъектов'),int) or s.get('количество_субъектов',-1)<0]
 добавить('Допустимость исходных параметров','соответствует' if not bad else 'несоответствие',f'Ошибочные системы: {bad or "нет"}','Проверены категории, субъекты, число и тип угроз','Исправить некорректные входные значения')
 total=sum(s['количество_субъектов'] for s in системы); unique=организация.get('число_субъектов_всех_систем')
 добавить('Согласованность численности','замечание' if total!=unique else 'соответствует',f'Сумма контуров {total}; заявлено уникальных {unique}','Сумма контуров может включать повторяющихся людей','Документировать пересечения; уникальную численность считать отдельно')
 mism=[s['номер'] for s in системы if s.get('заявленный_уз') and s['заявленный_уз']!=расчёты[s['номер']]['уровень']]
 добавить('Заявленный и рассчитанный УЗ','несоответствие' if mism else 'соответствует',f'Системы с расхождением: {mism or "нет"}','Сравнение значения из реестра с результатом функции','Обновить акт и обоснование уровня')
 threshold=расчёты.get('пороговый_тест',[]); threshold_ok=len(threshold)==3 and threshold[0]['количество']<100000 and threshold[1]['количество']==100000 and threshold[2]['количество']>100000
 добавить('Порог 100 000','соответствует' if threshold_ok else 'недостаточно_данных',f'Пороговый набор: {threshold}','Сравниваются 99 999, 100 000, 100 001','Провести граничный тест и сохранить результаты')
 refs=[e for s in системы for e in s.get('связанное_оборудование',[])]; known={e['название'] for e in расчёты.get('оборудование',[])}
 добавить('Ссылки оборудования на системы','соответствует' if not проблемы_оборудования else 'несоответствие',f'Проблемные записи: {len(проблемы_оборудования)}','Проверены существующие ссылки и классификация','Исправить инвентаризацию')
 добавить('Классификация ОТСС/ВТСС','несоответствие' if any('классификация' in str(p) for p in проблемы_оборудования) else 'соответствует',f'Ошибки оборудования: {проблемы_оборудования}','Проверены заполненность и логичность класса','Заполнить классификацию и обоснование')
 gaps=sum(len(x['пробелы']) for x in подбор.values())
 добавить('Требуемые и реализованные меры','замечание' if gaps else 'соответствует',f'Найдено пробелов мер: {gaps}','Сравнение по кодам мер','Внедрить отсутствующие меры и приложить подтверждения')
 добавить('СЗИ/СКЗИ и источники','соответствует' if len(справочник_сзи)>=5 and all(x.get('источник_сведений') for x in справочник_сзи) else 'замечание',f'Записей средств: {len(справочник_сзи)}','Проверено наличие карточек и источников','Подтвердить статус и класс по реестрам')
 гис=[s['номер'] for s in системы if s.get('является_гис')]; добавить('Применимость приказа №17','соответствует' if not гис or all(подбор[i]['проверка_гис']['рассмотрен'] for i in гис) else 'несоответствие',f'ГИС: {гис or "не выявлены"}','Для отмеченных ГИС отражена отдельная проверка','Отдельно проверить актуальные требования приказа №17')
 добавить('Обоснования условных мер','соответствует','В каталоге меры имеют условия применения','Условные меры не удаляются из каталога','Для неприменимых мер фиксировать письменное обоснование')
 добавить('Документы и дата отчёта','соответствует' if документы_готовы else 'недостаточно_данных','Отчёт и план формируются симулятором','Проверено наличие результирующих документов','Пересформировать отчёт при изменениях')
 score=max(0,min(100,100-8*gaps-6*len(проблемы_оборудования)-5*len(mism)))
 return {'пункты':пункты,'оценка':score,'дефекты':{'расхождение_заявленного_уз':mism,'пробелы_мер':gaps,'оборудование':проблемы_оборудования}}
